/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { tokenize, LexError } from './lexer.js'

const STAT_KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'tokens' && mode !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const source = readStdin()

  let tokens
  try {
    tokens = tokenize(source)
  } catch (err) {
    if (err instanceof LexError) {
      process.stderr.write(`error: ${err.line}:${err.col}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }

  let output
  if (mode === 'tokens') {
    output = tokens.map((t) => `${t.line}:${t.col} ${t.kind} ${t.text}\n`).join('')
  } else {
    const counts = new Map(STAT_KINDS.map((k) => [k, 0]))
    for (const t of tokens) {
      counts.set(t.kind, counts.get(t.kind) + 1)
    }
    const lines = STAT_KINDS.map((k) => `${k} ${counts.get(k)}\n`)
    lines.push(`total ${tokens.length}\n`)
    output = lines.join('')
  }

  process.stdout.write(output)
  process.exit(0)
}

